body.query:
query($address:String!, $chainId:Int!){vaultByAddress(address:$address,chainId:$chainId){
  address name symbol
  asset { symbol address decimals }
  chain { id network }
  state {
    timestamp blockNumber totalAssets totalAssetsUsd apy netApy fee
    allocation {
      supplyAssets supplyAssetsUsd supplyCapUsd
      market {
        marketId lltv
        loanAsset { symbol address }
        collateralAsset { symbol address }
        oracle { address }
        state { timestamp blockNumber supplyApy borrowApy utilization supplyAssetsUsd borrowAssetsUsd liquidityAssetsUsd collateralAssetsUsd }
      }
    }
  }
}}

query($m0:String!){m0:marketById(marketId:$m0,chainId:1){
marketId lltv
loanAsset { symbol address }
collateralAsset { symbol address }
oracle { address }
state { timestamp blockNumber supplyApy borrowApy utilization
        supplyAssetsUsd borrowAssetsUsd liquidityAssetsUsd collateralAssetsUsd }
}}
